    shifted_vowels = {v: chr(ord(v) + 2) for v in vowels}
    shifted_vowels.update({v.upper(): shifted_vowels[v].upper() for v in vowels})

    encoded_message = []
    for char in message:
        if char.isalpha():
            if char.lower() in vowels:
                new_char = shifted_vowels[char]
            else:
                new_char = char
            encoded_message.append(new_char.swapcase())
        else:
            encoded_message.append(char)

    return ''.join(encoded_message)

# Examples
print(encode('test'))  # 'TGST'
print(encode('This is a message'))  # 'tHKS KS C MGSSCGG'
```

