def f(n):
    def factorial(i):
        return 1 if i == 0 or i == 1 else i * factorial(i - 1)

    def sum_to_i(i):
        return i * (i + 1) // 2

    result = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            result.append(factorial(i))
        else:
            result.append(sum_to_i(i))

    return result
```

