    days_in_month = {
        1: 31, 2: 29, 3: 31,
        4: 30, 5: 31, 6: 30,
        7: 31, 8: 31, 9: 30,
        10: 31, 11: 30, 12: 31
    }

    # Check day range
    if day < 1 or day > days_in_month[month]:
        return False

    # Additional check for February 29 in non-leap years
    if month == 2 and day == 29:
        if year % 4 != 0 or (year % 100 == 0 and year % 400 != 0):
            return False

    return True
