def find_max(words):
    def unique_char_count(word):
        return len(set(word))

    # Sort words by lexicographical order first to ensure correct order in case of ties
    words.sort()

    # Find the word with the maximum number of unique characters
    max_word = max(words, key=unique_char_count)

    return max_word
```

```python
def find_max(words):
    def unique_char_count(word):
        return len(set(word))

    max_word = ""
    max_unique_count = 0

    for word in words:
        unique_count = unique_char_count(word)
        if (unique_count > max_unique_count) or (unique_count == max_unique_count and word < max_word):
            max_word = word
            max_unique_count = unique_count

    return max_word
```

